for _,def in ipairs({{"friends","Friends"},{"guild","Guild"},{"hearth","Hearthstone"},{"reds","Reds QOL settings"},{"trainer","Trainer spells"},{"map","World map"},{"bags","Bags"}}) do
 local key=def[1]
 top[#top+1]={type="choice",label=def[2],options={{"Off","off"},{"Left","left"},{"Right","right"}},get=function(s) return s.topbar.layout[key] end,set=function(s,v) s.topbar.layout[key]=v end,when=function(s) return s.topbar.enabled end}
